import {esc}from'./format.js';
export const ROLES={operator:'Operator',engineer:'Inginer',management:'Management'};
const links=[['overview','◫','Privire de ansamblu'],['operator','◎','Post de lucru'],['diagrams','◇','Diagrame & fluxuri'],['library','▤','Bibliotecă'],['staffing','♙','Utilaje & personal'],['calibration','◉','Calibrare date'],['results','◷','Rezultate simulare'],['scenarios','⇄','Scenarii'],['engineering','⌘','MBSE & trasabilitate'],['repository','▦','Toate obiectele'],['variables','ƒ','Variabile'],['method','?','Ghid & limite'],['bibliography','▧','Bibliografie & surse']];
export function navigation({page,role,runtime}){const primary=role==='operator'?['operator','overview','calibration','staffing']:role==='management'?['overview','results','scenarios','calibration']:['overview','diagrams','library','staffing','calibration','results','scenarios'];const button=([id,icon,label])=>`<button class="nav ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</button>`;return `<aside class="sidebar"><a class="brand" href="#"><span class="logo">F</span><span>factory<span class="brand-light">studio</span></span></a><div class="workspace-label">WORKSPACE · 0.4</div><label class="role-label">Spațiu de lucru<select id="workspace-role">${Object.entries(ROLES).map(([k,v])=>`<option value="${k}" ${role===k?'selected':''}>${v}</option>`).join('')}</select></label><nav aria-label="Navigare principală"><div class="navlabel">${ROLES[role]}</div>${links.filter(([id])=>primary.includes(id)||id==='bibliography').map(button).join('')}<details class="nav-more" ${primary.includes(page)?'':'open'}><summary>Toate instrumentele</summary>${links.filter(([id])=>!primary.includes(id)&&id!=='bibliography').map(button).join('')}</details></nav><footer><div class="runtime-label"><span class="status-dot"></span>${runtime.mode==='docker'?'Docker · 4 servicii':'Browser · calcul local'}</div><small>Modurile adaptează interfața.<br>Nu sunt roluri de securitate.</small></footer></aside>`}
export function topbar({m,role,busy,undo,redo,runtime,cloudRevision}){return `<header class="topbar"><div class="project-heading"><span class="crumb">PROIECT / ${ROLES[role].toUpperCase()}</span><strong>${esc(m.name)}</strong><small>${m.nodes.length} obiecte · ${m.edges.length} conexiuni</small></div><div class="actions"><button data-action="undo" aria-label="Anulează ultima modificare" title="Ctrl+Z" ${undo.length&&!busy?'':'disabled'}>↶</button><button data-action="redo" aria-label="Refă modificarea" title="Ctrl+Shift+Z" ${redo.length&&!busy?'':'disabled'}>↷</button>${runtime.mode==='docker'?`<button data-action="cloud-models">Modele salvate</button><button data-action="cloud-save">Salvează în Docker${cloudRevision?' · r'+cloudRevision:''}</button>`:''}<details class="project-menu"><summary>Proiect ▾</summary><div><button data-action="import">Importă JSON</button><button data-action="export">Exportă JSON</button><button data-action="new-model">Model nou</button></div></details><span class="save-indicator" title="Model salvat automat în acest browser">● Local</span></div></header>`}
export function simulationControls({m,busy,runtime}){return `<section class="simcontrols" aria-label="Configurare simulare"><div class="sim-label"><span>◷</span><div><b>Scenariu de simulare</b><small>${runtime.mode==='docker'?'Motor dedicat Docker':'Motor local în browser'}</small></div></div><label>Orizont <input id="hours" type="number" min=".01" max="168" step=".1" value="${m.settings.hours}" ${busy?'disabled':''}> ore</label><details class="simulation-options"><summary>Opțiuni</summary><div><label>Seed<input id="seed" type="number" min="0" max="2147483647" value="${m.settings.seed}" ${busy?'disabled':''}></label><label>Replicări<input id="replications" type="number" min="1" max="20" value="${m.settings.replications}" ${busy?'disabled':''}></label></div></details><button class="primary" data-action="run" ${busy?'disabled':''}>${busy?'Calcul în curs…':'▷ Simulează'}</button>${busy?'<button data-action="cancel">Oprește</button>':''}</section>`}
